{
  "summary": "Quadratic-mean mixtures lead; periodic MA1 modulation is best, but MA1+MA3 and LIN-modulated MA1+RQ are within 1.5 AIC. Modulation benefits therefore remain uncertain. Final tests substitute components around leading models, then reverse which mixture component receives periodic or LIN modulation. These comparisons retain the quadratic mean, which improved all directly compared structures.",
  "proposals": [
    {
      "kernel_id": 56,
      "mean_id": 4,
      "reason": "Replace RQ with MA3 in the leader; also tests periodic modulation against MA1+MA3."
    },
    {
      "kernel_id": 68,
      "mean_id": 4,
      "reason": "Replace periodically modulated MA1 with MA3 while holding RQ and quadratic mean fixed."
    },
    {
      "kernel_id": 17,
      "mean_id": 4,
      "reason": "Replace MA3 with MA5 in the strongest unmodulated mixture to test smoother residual structure."
    },
    {
      "kernel_id": 86,
      "mean_id": 4,
      "reason": "Explore periodic modulation of RQ rather than MA1, retaining both mixture primitives."
    },
    {
      "kernel_id": 81,
      "mean_id": 4,
      "reason": "Explore LIN modulation of RQ rather than MA1, retaining both mixture primitives."
    },
    {
      "kernel_id": 51,
      "mean_id": 4,
      "reason": "Reserve: test LIN modulation within MA1+MA3, directly comparable with periodic and unmodulated versions."
    },
    {
      "kernel_id": 57,
      "mean_id": 4,
      "reason": "Reserve: replace RQ with MA5 in the periodic leader while retaining modulated MA1."
    }
  ]
}
